import{_ as t,o as s,c as o,ag as a}from"./chunks/framework.-5_vvMqw.js";const u=JSON.parse('{"title":"Continue a session locally","description":"","frontmatter":{},"headers":[],"relativePath":"local-sessions.md","filePath":"local-sessions.md","lastUpdated":1793920270000}'),i={name:"local-sessions.md"};function n(r,e,d,l,h,c){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="continue-a-session-locally" tabindex="-1">Continue a session locally <a class="header-anchor" href="#continue-a-session-locally" aria-label="Permalink to &quot;Continue a session locally&quot;">​</a></h1><p>Take an existing conversation from AgentHub to a matching local checkout. The transfer copies conversation history; it does <strong>not</strong> copy the repository, uncommitted project files, or session attachments. Check out the project locally first and download attachments separately.</p><table tabindex="0"><thead><tr><th>Agent</th><th>Continue locally</th><th>Return the local conversation to AgentHub</th></tr></thead><tbody><tr><td>Claude Code</td><td><strong>Continue locally</strong> in the web app, or the <code>session_take_local</code> MCP tool</td><td>The same dialog, or the <code>session_hand_back</code> MCP tool</td></tr><tr><td>Codex</td><td>Skill: <code>pull</code>, then <code>codex resume</code></td><td>Not implemented</td></tr><tr><td>Other agents</td><td>Not available</td><td>Not available</td></tr></tbody></table><h2 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude Code&quot;">​</a></h2><p>From Open AgentHub 1.17, a Claude Code session moves to your computer and back without a personal API token or a plugin. Three ways lead to the same result; pick the one that fits:</p><table tabindex="0"><thead><tr><th>Way</th><th>What you need</th><th>Who writes the files</th></tr></thead><tbody><tr><td><strong>Continue locally</strong> button on the session page</td><td><code>curl</code>, <code>tar</code> (built into Linux, macOS, Windows 10+)</td><td>A command you paste into a terminal</td></tr><tr><td>Remote MCP connection (OAuth sign-in) in your local Claude Code</td><td>The <a href="/docs/mcp">built-in MCP endpoint</a></td><td>A command your local Claude Code runs</td></tr><tr><td><a href="/docs/mcp#local-stdio">Stdio MCP server</a> with a personal API token</td><td>A checkout of AgentHub and Node</td><td>The MCP server itself</td></tr></tbody></table><p>Only the session owner can take a session local or hand it back. It works in every edition.</p><h3 id="what-happens" tabindex="-1">What happens <a class="header-anchor" href="#what-happens" aria-label="Permalink to &quot;What happens&quot;">​</a></h3><ol><li><strong>Take it local.</strong> AgentHub pauses the session: its pod saves the conversation and stops, so the conversation is never answered in two places at once. Then it prepares the conversation for the local directory you named and writes it to <code>~/.claude/projects/</code>, where <code>claude --resume</code> finds it.</li><li><strong>Continue</strong> with <code>claude --resume &lt;id&gt;</code> in that directory. Claude Code tells the model that the working directory changed; the conversation, including tool results, is the same.</li><li><strong>Hand it back.</strong> Quit the local Claude Code first so the conversation is complete. AgentHub stores the local conversation as the session&#39;s own and resumes the session in the hub with every turn you took locally. Stop using the local copy afterwards.</li></ol><p>The local directory should be a checkout of the same repository. The conversation moves, the code does not: commit and push your local changes as usual.</p><h3 id="in-the-web-app" tabindex="-1">In the web app <a class="header-anchor" href="#in-the-web-app" aria-label="Permalink to &quot;In the web app&quot;">​</a></h3><p>Open the session and choose <strong>⇩ Continue locally</strong>.</p><ol><li>Enter the <strong>absolute</strong> path of your local project directory, for example <code>/home/me/project</code> or <code>C:\\Users\\me\\project</code>. The browser remembers it for this session.</li><li>Choose <strong>bash / zsh</strong> or <strong>PowerShell</strong>.</li><li>Under <strong>Take it local</strong>, choose <strong>Pause and create command</strong> (or <strong>Create command</strong> when the session is already paused), copy the command and run it in a terminal. It creates the directory if needed, downloads and unpacks the conversation, and starts <code>claude --resume</code>.</li><li>When you are done, quit Claude Code and, under <strong>Hand it back</strong>, choose <strong>Create hand-back command</strong>. Leave <strong>Resume the session after the upload</strong> ticked to continue in the hub right away. Run the command; it answers with the session&#39;s new state.</li></ol><p>Each command contains a <strong>single-use link that expires after 15 minutes</strong>. It works once, for this session and this direction only; create a new command if it expired. Treat it like a password until it is used: anyone with the command can download the conversation. The secret is sent in a request header, so it does not show up in proxy or ingress access logs.</p><h3 id="with-the-remote-mcp-endpoint" tabindex="-1">With the remote MCP endpoint <a class="header-anchor" href="#with-the-remote-mcp-endpoint" aria-label="Permalink to &quot;With the remote MCP endpoint&quot;">​</a></h3><p>With AgentHub&#39;s <a href="/docs/mcp">remote MCP endpoint</a> connected to your local Claude Code, ask for example <em>&quot;take AgentHub session <code>a1b2c3</code> local into /home/me/project&quot;</em>.</p><ul><li><code>session_take_local</code> (<code>sessionId</code>, <code>directory</code>, <code>confirm</code>): without <code>confirm</code> it changes nothing and lists what it would do, so Claude Code can ask you first. With <code>confirm</code> it pauses the session and returns the link and the bash and PowerShell commands. Claude Code can run the command in its shell; start <code>claude --resume</code> in a new terminal yourself.</li><li><code>session_hand_back</code> (<code>sessionId</code>, <code>directory</code>, <code>resume</code>): returns the upload command.</li></ul><p>The remote endpoint runs in the hub and cannot write to your disk, which is why it answers with a command rather than writing the files.</p><h3 id="with-the-stdio-mcp-server" tabindex="-1">With the stdio MCP server <a class="header-anchor" href="#with-the-stdio-mcp-server" aria-label="Permalink to &quot;With the stdio MCP server&quot;">​</a></h3><p>The <a href="/docs/mcp#local-stdio">stdio MCP server</a> runs on your computer with a personal API token and writes the files itself, so there is no command to paste:</p><ul><li><code>session_take_local</code> (<code>sessionId</code>, <code>directory</code>, <code>confirm</code>, <code>overwrite</code>) pauses the session (with <code>confirm</code>), writes the conversation and answers with the <code>resumeCommand</code> to run in a new terminal. It honours <code>CLAUDE_CONFIG_DIR</code> if you set one.</li><li><code>session_hand_back</code> (<code>sessionId</code>, <code>directory</code>, <code>resume</code>, <code>localSessionId</code>) packs and uploads the local conversation and resumes the session. <code>localSessionId</code> picks another local conversation, for example after <code>claude --resume --fork-session</code>.</li></ul><h3 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h3><ul><li>The session needs a stored conversation, which it has once it has run.</li><li>A session running in the hub cannot be handed back: pause it first. The hub refuses, because the running pod would overwrite the upload when it stops.</li><li>A conversation already on your computer with other content is <strong>not</strong> overwritten: the pasted command stops at <code>tar</code>, the stdio tool answers <code>local_transcript_differs</code>. Hand that one back first, or pass <code>overwrite</code> to the stdio tool if you want to discard it.</li><li>The links need <strong>FrontendOrigin</strong> to be set on the instance (the chart sets it); otherwise only the stdio server works.</li><li>Session files and attachments are not part of the transfer; download them separately.</li></ul><h3 id="the-plugin-earlier-releases" tabindex="-1">The plugin (earlier releases) <a class="header-anchor" href="#the-plugin-earlier-releases" aria-label="Permalink to &quot;The plugin (earlier releases)&quot;">​</a></h3><p>Before 1.17, the <a href="https://github.com/open-agenthub/plugins" target="_blank" rel="noreferrer">plugins repository</a> offered the <strong>agenthub-sessions</strong> plugin with <code>pull</code> and <code>push</code> commands and a personal API token. It still works, but the steps above need neither the plugin nor a token in your shell.</p><h2 id="codex-install-and-use-the-skill" tabindex="-1">Codex: install and use the skill <a class="header-anchor" href="#codex-install-and-use-the-skill" aria-label="Permalink to &quot;Codex: install and use the skill&quot;">​</a></h2><p>Copy <code>codex/skills/agenthub-session-transfer</code> from the <a href="https://github.com/open-agenthub/plugins/tree/main/codex/skills/agenthub-session-transfer" target="_blank" rel="noreferrer">plugins repository</a> into your local Codex skills directory. The helper requires <strong>Node 20+</strong> and local Codex. Ask Codex to use <strong>agenthub-session-transfer</strong>, providing the hub session ID or URL and local checkout. It reads <code>AGENTHUB_URL</code> and <code>AGENTHUB_TOKEN</code>, or <code>~/.agenthub/cli.json</code>; create a personal token in <strong>Settings → API tokens</strong> (it starts with <code>oah_</code>) and keep it out of chat messages. If using the helper manually, replace <code>&lt;skill-dir&gt;</code> below with the installed skill&#39;s absolute path. Configure the hub URL and personal token locally first.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-di</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/scripts/agenthub-codex.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-di</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/scripts/agenthub-codex.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hub-session-id-or-ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-di</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/scripts/agenthub-codex.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">hub-session-id-or-ur</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dir</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">local-checkou</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>The helper imports one Codex rollout, assigns a fresh local thread UUID, and rewrites its working-directory metadata. Run the returned <code>codex resume &lt;local-thread-id&gt;</code> command from your chosen checkout in a new Codex conversation. The hub ID and local UUID are different. If needed, select a rollout explicitly with <code>--session &lt;rollout-uuid&gt;</code>.</p><p>This is an import only: it does not pause or change the hub session and provides no push command. A running session can be copied from its latest stored snapshot, which may omit newer turns. It does not restore pod authentication, configuration, hooks, MCP servers, or skills. Desktop sidebar discovery may require opening the imported thread through Codex first.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message or symptom</th><th>Next step</th></tr></thead><tbody><tr><td><code>confirmationRequired</code></td><td>The session is running; call the tool again with <code>confirm</code> after deciding to pause it.</td></tr><tr><td><code>transcript_missing</code> / no stored state</td><td>The session needs an archived run; a never-started session has nothing to transfer.</td></tr><tr><td><code>agent_not_supported</code></td><td>Only Claude Code sessions move this way; for Codex use the skill.</td></tr><tr><td><code>directory_invalid</code></td><td>Give the absolute path of the local directory.</td></tr><tr><td><code>session_live</code></td><td>Pause the session in AgentHub, wait until it shows Paused, and retry.</td></tr><tr><td><code>local_transcript_differs</code> / <code>tar</code> reports the file exists</td><td>A different local copy is there; hand it back first, or overwrite it on purpose.</td></tr><tr><td><code>transcript_unrelated</code></td><td>The local conversation does not continue this session; check the session ID and directory.</td></tr><tr><td><code>link_invalid</code> (HTTP 404)</td><td>The link expired or was used; create a new command.</td></tr><tr><td><code>origin_not_configured</code></td><td>Ask the administrator to set FrontendOrigin, or use the stdio server.</td></tr><tr><td><code>pod_still_stopping</code></td><td>The session is paused but still saving; try again in a minute.</td></tr><tr><td>Codex helper: Not configured / HTTP 401</td><td>Set the hub URL and a valid personal API token locally.</td></tr><tr><td>Codex helper: several transcripts</td><td>Inspect the choices and pass <code>--session &lt;id&gt;</code>.</td></tr></tbody></table><p>See the <a href="https://github.com/open-agenthub/plugins/blob/main/codex/skills/agenthub-session-transfer/SKILL.md" target="_blank" rel="noreferrer">Codex skill</a> and the <a href="https://github.com/open-agenthub/open-agenthub/blob/main/docs/session-transfer.md" target="_blank" rel="noreferrer">design notes</a> for implementation details.</p>`,33)])])}const k=t(i,[["render",n]]);export{u as __pageData,k as default};
